package bootstrap
import("context";"errors";"testing";"time";"github.com/oublie6/awesome-zero-platform/server/business/doudizhu/application";"github.com/oublie6/awesome-zero-platform/server/business/doudizhu/domain";ddzruntime "github.com/oublie6/awesome-zero-platform/server/business/doudizhu/infrastructure/runtime")
type r9FailDeal struct{*dealerWriterFixture;fail bool;reject bool}
func(w *r9FailDeal)MarkHandDealt(ctx context.Context,a domain.AccountID,c application.Command)(application.CommandResult,error){if w.fail{return application.CommandResult{},errors.New("injected durable write failure")};if w.reject{return application.CommandResult{Accepted:false},nil};return w.dealerWriterFixture.MarkHandDealt(ctx,a,c)}
type r9FailTrack struct{called int;fail bool}
func(x *r9FailTrack)TrackBidding(context.Context,domain.AccountID,domain.HandID)error{x.called++;if x.fail{return errors.New("injected lifecycle tracking failure")};return nil}
func TestRound9DealtNotificationFailureOrdering(t *testing.T){for _,mode:=range []string{"write-error","write-rejected","tracking-error"}{t.Run(mode,func(t *testing.T){s:=&dealerStoreFixture{snaps:map[domain.HandID]domain.HandSnapshot{"hand-1":{ID:"hand-1",Phase:domain.HandDealing,Version:5,BeaconPlan:domain.BeaconPlan{Provider:ddzruntime.DrandQuicknetProvider,Round:"1234567"},Seats:[3]domain.HandSeat{{Seat:1,AccountID:"player-1"}}}},seq:9};w:=&r9FailDeal{dealerWriterFixture:&dealerWriterFixture{store:s},fail:mode=="write-error",reject:mode=="write-rejected"};tr:=&r9FailTrack{fail:mode=="tracking-error"};d,e:=newFairAutoDealer(s,w,tr,&dealerBeaconFixture{ready:true},&dealerIDsFixture{},dealerClockFixture{},time.Minute);if e!=nil{t.Fatal(e)};notify:=0;d.notifyDealt=func(context.Context,domain.HandID){notify++};_,e=d.ProcessOnce(context.Background());if e==nil||notify!=0{t.Fatalf("failure was published: err=%v notify=%d",e,notify)};if mode!="tracking-error"{if tr.called!=0{t.Fatal("tracking preceded durable commit")};w.fail=false;w.reject=false;if _,e=d.ProcessOnce(context.Background());e!=nil||notify!=1{t.Fatalf("retry failed %v notify=%d",e,notify)}};before:=notify;_,_=d.ProcessOnce(context.Background());if notify!=before||w.dealt!=1{t.Fatalf("duplicate notification/deal: %d %d",notify,w.dealt)}})}}
